#!/usr/bin/env node
// === api-dsl emitter — 1:1 restoration of old codegen ===
// Ported from: gen_api_controllers/ (JS: builder.mjs + tpl_controller.mjs + tpl_dsl.mjs)
// Generates: <Agg>ApiController.scala + routes fragment
// Pattern matches ingested-app golden (e.g., ConceptApiController.scala):
//   - // @generated by gen_api_layer
//   - package controllers, fixed import set
//   - @Singleton class with api: Endpoint + repository injection
//   - B2 DSL endpoints: api.<tier>.write[Req](...).apply[OkReceipt]
//   - Req VO case classes at file tail
// Usage: node emit.mjs <spec.json> <out-dir>
//   spec: { aggregate, basePkg, commands: [{ name, actionName, tier, params,
//           reqFields, idGuard, instantGuard, ... }] }

import { readFileSync, writeFileSync, mkdirSync } from "fs";
import { join } from "path";

const [specPath, outDir] = process.argv.slice(2);
const spec = JSON.parse(readFileSync(specPath, "utf8"));
mkdirSync(outDir, { recursive: true });

const agg = spec.aggregate;           // e.g., "Concept"
const basePkg = spec.basePkg || "net.imadz.metarch";
const ctrlName = `${agg}ApiController`;
const commands = spec.commands || [];

// ─── Helpers ───
const firstLower = (s) => s.charAt(0).toLowerCase() + s.slice(1);
const kebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();

// ─── Endpoint rendering (B2 DSL) ───
// Matches tpl_dsl.mjs renderStandardEndpoint
function renderEndpoint(cmd) {
  const tier = cmd.tier || "tenant";
  const actionName = cmd.actionName || firstLower(cmd.name);
  const reqName = `${cmd.name}Req`;
  const reply = `${cmd.name}Reply`;

  // Gate declaration
  const gate = tier === "tenant"
    ? {
        comment: "tenant 档——api.tenant.write + CommandRoleMap 命令粒度角色",
        decl: `api.tenant.write[${reqName}](CommandRoleMap.ofCommand("${cmd.name}"): _*)`,
        ctx: "(ts, req)",
      }
    : tier === "global"
    ? {
        comment: "global 档——api.global.write 空 roles",
        decl: `api.global.write[${reqName}]()`,
        ctx: "(gc, req)",
      }
    : {
        comment: "anonymous 档——api.anonymous 免登录",
        decl: `api.anonymous.write[${reqName}]`,
        ctx: "(req, body)",
      };

  // ID guard
  const idGuard = cmd.idGuard;
  let guardOpen = "", guardClose = "";
  if (idGuard) {
    const pairs = idGuard.pairs || [];
    const cids = idGuard.cids || [];
    guardOpen = `          IdGuard.parse(${pairs.join(", ")}) match {
            case Right(Seq(${cids.join(", ")})) =>`;
    guardClose = `            case Left(err) => Future.successful(Left(err))
          }`;
  }

  // Instant guard (outer)
  const instantGuard = cmd.instantGuard;
  let instantOpen = "", instantClose = "";
  if (instantGuard) {
    instantOpen = `          InstantGuard.parse(${instantGuard.pairs}) match {
            case Right(Seq(${instantGuard.names})) =>`;
    instantClose = `            case Left(err) => Future.successful(Left(err))
          }`;
  }

  // Ask pipeline
  const entityExpr = cmd.entityExpr || "id";
  const ctorArgs = cmd.ctorArgs || "";
  const dvExpr = cmd.dvExpr || "JsNull";

  const askBody = `          repository.entityRef(${entityExpr}).ask {
            (replyTo: akka.actor.typed.ActorRef[${reply}]) => ${cmd.name}(${ctorArgs}${ctorArgs ? ", " : ""}replyTo)
          }.map { reply =>
            reply.error.fold[Either[net.imadz.common.auth.ApiError, net.imadz.metarch.infrastructure.api.OkReceipt]](
              Right(net.imadz.metarch.infrastructure.api.OkReceipt(${entityExpr}, ${dvExpr}))
            )(e => Left(net.imadz.common.auth.ApiError.badRequest(e.code, e.message)))
          }`;

  // Sig: (id: String) for path-param commands, () for body-only
  const sig = cmd.sig || (cmd.pathParam ? `(${cmd.pathParam}: String)` : "");

  const noteAnchor = cmd.noteId ? `  // @knowledge ${cmd.noteId}\n` : "";

  return `${noteAnchor}  /** B2 DSL：${cmd.name}（${gate.comment}） */
  def ${actionName}${sig}: play.api.mvc.Action[play.api.mvc.AnyContent] =
    ${gate.decl}
      .apply[net.imadz.metarch.infrastructure.api.OkReceipt] { ${gate.ctx} =>
${instantOpen}${guardOpen}
${askBody}
${guardClose}${instantClose}
      }
`;
}

// ─── Req VO rendering ───
function renderReqVo(cmd) {
  const reqName = `${cmd.name}Req`;
  const fields = (cmd.reqFields || []).map((f) => `${f.name}: ${f.type}`).join(", ");
  const noteAnchor = cmd.noteId ? `// @knowledge ${cmd.noteId}\n` : "";
  return `${noteAnchor}/** M2: 命令载荷 VO——typed Reads 派生 */
final case class ${reqName}(${fields})
object ${reqName} {
  implicit val reads: play.api.libs.json.Reads[${reqName}] = play.api.libs.json.Json.reads
}`;
}

// ─── Controller assembly (tpl_controller.mjs) ───
function renderController() {
  const flags = spec.flags || {};
  const extraInjection = [
    flags.needsParkRepo
      ? `, parkConceptViewRepository: ${basePkg}.application.projection.repository.ParkConceptDecisionViewRepository` : "",
    flags.needsRegisterFlow ? `, registerUserFlow: ${basePkg}.application.RegisterUserFlow` : "",
    flags.needsDoRFlow ? `, requestDoRFlow: ${basePkg}.application.RequestDoRFlow` : "",
  ].join("");

  const dslInjection = `api: net.imadz.common.auth.Endpoint, `;

  const imports = [
    "import javax.inject.{Inject, Singleton}",
    `import ${basePkg}.application.aggregates.${agg}Protocol._`,
    `import ${basePkg}.application.aggregates.repository.${agg}Repository`,
    "import net.imadz.common.auth.ApiError",
    `import ${basePkg}.infrastructure.auth.CommandRoleMap`,
    `import ${basePkg}.infrastructure.api.{IdGuard, InstantGuard, OkReceipt}`,
    "import play.api.libs.json.{JsValue, Json}",
    "import play.api.mvc._",
    "",
    "import scala.concurrent.ExecutionContext",
    "import scala.concurrent.Future",
    "import scala.concurrent.duration._",
  ].join("\n");

  const endpoints = commands.map(renderEndpoint).join("\n");
  const reqVos = commands.map(renderReqVo).join("\n\n");

  const emptyBodyReads = flags.aggHasEmptyBody ? `
  /** 空 body 命令通道（write[JsObject]）：任意合法 JSON 体即过 */
  private implicit val emptyBodyReads: play.api.libs.json.Reads[play.api.libs.json.JsObject] =
    play.api.libs.json.Reads(_ => play.api.libs.json.JsSuccess(play.api.libs.json.Json.obj()))` : "";

  return `// @generated by api-dsl (truthsrc)
// @knowledge-release 1.0.0
package controllers

${imports}

/** ${ctrlName}: ${agg} 命令 API（api-dsl 直出·B2 DSL 形态） */
@Singleton
class ${ctrlName} @Inject() (${dslInjection}repository: ${agg}Repository${extraInjection}, val cc: ControllerComponents)(implicit ec: ExecutionContext) extends BaseController {

  override def controllerComponents: ControllerComponents = cc
  private implicit val timeout: akka.util.Timeout = akka.util.Timeout(5.seconds)${emptyBodyReads}

${endpoints}
}
${reqVos ? "\n" + reqVos + "\n" : ""}
`;
}

// ─── Routes fragment (RoutesBuilder) ───
// Format: METHOD(9-col) + path + 2 spaces + controllers.<Ctrl>.<action>(params)
function renderRoutes() {
  const lines = commands
    .filter((c) => !c.skip)
    .map((c) => {
      const method = (c.httpMethod || "POST").padEnd(9, " ");
      const path = c.routePath || `/api/${kebab(agg)}/${kebab(c.name)}`;
      const params = c.routeParams ? `(${c.routeParams})` : "";
      const action = c.actionName || firstLower(c.name);
      return `${method}${path}  controllers.${ctrlName}.${action}${params}`;
    });
  if (!lines.length) return null;
  return `# >>> codegen:controllers (do not edit inside; regenerated) >>>
${lines.join("\n")}
# <<< codegen:controllers <<<
`;
}

// ─── Emit ───
const controller = renderController();
writeFileSync(join(outDir, `${ctrlName}.scala`), controller);

const routes = renderRoutes();
if (routes) {
  writeFileSync(join(outDir, "routes.fragment"), routes);
}

console.log(`emitted ${ctrlName}.scala${routes ? ", routes.fragment" : ""} (${commands.length} endpoints)`);
